attribute "tsugumi";
namespace lung;
table Specifications { value:string; }
table Outputs { specifications:Specifications (required, tsugumi: "file"); }
root_type Outputs;

{ pkgs, inputs, params }:
{
  run = inputs.tsugumi.rCard { src = ./src; packages = ps: [ ps.survival ps.ggplot2 ]; };
}

{
  "language": "r",
  "inputs": [
    {
      "name": "lung"
    }
  ],
  "retainArtifact": true,
  "artifactOutput": "specifications",
  "filesystem": true,
  "params": [
    {
      "name": "exposure",
      "type": "string",
      "data": "female"
    },
    {
      "name": "subsets",
      "type": "string[]",
      "data": [
        "TRUE",
        "age < 65",
        "age >= 65",
        "ph.ecog == 0",
        "ph.ecog == 1",
        "ph.ecog >= 2"
      ]
    },
    {
      "name": "adjustments",
      "type": "string[]",
      "data": [
        "",
        "age",
        "age + ph.ecog",
        "age + ph.ecog + ph.karno + wt.loss"
      ]
    }
  ]
}
